{"actions": [{"content": "import re

SEMVER_PATTERN = re.compile(r'^(\d+\.\d+\.\d+)$')

def latest_stable(versions):
    stable = [v for v in versions if SEMVER_PATTERN.match(v)]
    if not stable:
        return None
    # Convert to tuple of ints for numeric comparison
    def parse(v):
        parts = v.split('.')
        return tuple(int(p) for p in parts)
    return max(stable, key=parse)
", "op": "write", "path": "src/versions.py"}]}

