{"actions": [{"content": "import re

def redact(text):
    pattern = r'(token|api_key)\s*=\s*[^\s;]+'
    def replacer(m):
        key = m.group(1)
        # Preserve case of the key (since group(1) returns as matched)
        return key + '=[REDACTED]'
    return re.sub(pattern, replacer, text, flags=re.IGNORECASE)
", "op": "write", "path": "src/redact.py"}]}

