{"actions": [{"content": "import re

def redact(text):
    # Pattern matches fields starting with token= or api_key= (case-insensitive)
    # It captures the field name (including optional 's' for api_key) and replaces the value
    # The value is everything until whitespace, semicolon, or end of string
    return re.sub(r'(?i)(token\s*=|api_key\s*=)\s*[^\s;]+', r'\1[REDACTED]', text)
", "op": "write", "path": "src/redact.py"}]}

