{"actions": [{"content": "def chunks(items, size):
    if size <= 0:
        raise ValueError("size must be positive")
    result = []
    current = []
    for item in items:
        current.append(item)
        if len(current) == size:
            result.append(current)
            current = []
    if current:
        result.append(current)
    return result
