{"actions": [{"content": "def resolve(defaults, file_values, env_values):
    # start with defaults copy
    result = defaults.copy()
    # apply file_values over defaults, ignoring None values
    for k, v in file_values.items():
        if v is not None:
            result[k] = v
    # apply env_values over everything, ignoring None values
    for k, v in env_values.items():
        if v is not None:
            result[k] = v
    return result", "op": "write", "path": "src/precedence.py"}]}

