{"actions": [{"content": "def dependency_order(graph):
    # Compute in-degree (number of dependencies) for each node
    in_degree = {node: 0 for node in graph}
    # Also include nodes that appear as dependencies but not as keys
    for deps in graph.values():
        for dep in deps:
            if dep not in in_degree:
                in_degree[dep] = 0
    for deps in graph.values():
        for dep in deps:
            in_degree[dep] += 1

    # Collect all nodes: keys + dependency-only nodes
    all_nodes = set(graph.keys())
    for deps in graph.values():
