{"actions": [{"content": "def dependency_order(graph):
    # Find all nodes including those that only appear as dependencies
    all_nodes = set(graph.keys())
    for deps in graph.values():
        all_nodes.update(deps)

    # Build in-degree map and adjacency list
    in_degree = {node: 0 for node in all_nodes}
    adjacency = {node: [] for node in all_nodes}
    for node, deps in graph.items():
        for dep in deps:
            adjacency[dep].append(node)
            in_degree[node] += 1

    # Kahn's algorithm with sorted list for deterministic order
    queue = sorted([node for node in all_nodes if in_degree[node] == 0])
    result = []
    while queue:
        node = queue.pop(0)
        result.append(node)
        for neighbor in sorted(adjacency[node]):
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)
                queue.sort()

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")
    return result
", "op": "write", "path": "src/order.py"}]}

