{"actions": [{"content": "import re

def parse_duration(text):
    # Pattern: digits, optional fractional part, followed by ms, s, or m
    match = re.fullmatch(r'(\d+)(?:\.\d+)?(ms|s|m)', text)
    if not match:
        raise ValueError(f"Invalid duration: {text}")
    number_str = text[:match.start(2)]  # includes fractional part if present
    unit = text[match.start(2):]
    # We already know number_str is a valid non-negative number from regex
    # But we enforce integer only (no fractional part)
    if '.' in number_str:
        raise ValueError(f"Invalid duration: {text}")
    number = int(number_str)
    # Negative check is unnecessary because regex only matches digits
    if unit == 'ms':
        return number
    elif unit == 's':
        return number * 1000
    elif unit == 'm':
        return number * 60 * 1000
    else:
        raise ValueError(f"Invalid duration: {text}")
", "op": "write", "path": "src/duration.py"}]}

