{"actions": [{"content": "import re

def parse_duration(text):
    # Allow optional whitespace for robustness, though tests don't require it
    m = re.fullmatch(r'\s*(\d+)\s*(ms|s|m)\s*', text)
    if not m:
        raise ValueError(f'Invalid duration: {text!r}')
    value = int(m.group(1))
    unit = m.group(2)
    # No negative check needed as \d+ ensures non-negative integer
    if unit == 'ms':
        return value
    elif unit == 's':
        return value * 1000
    else:  # 'm'
        return value * 60000
", "op": "write", "path": "src/duration.py"}]}

