{"actions": [{"content": "def resolve(defaults, file_values, env_values):
    result = {}
    for key, value in defaults.items():
        result[key] = value
    for key, value in file_values.items():
        if value is not None:
            result[key] = value
    for key, value in env_values.items():
        if value is not None:
            result[key] = value
    return result
", "op": "write", "path": "src/precedence.py"}]}

