def dependency_order(graph):
    # Determine all nodes, including those that appear only as dependencies
    all_nodes = set(graph.keys())
    for deps in graph.values():
        all_nodes.update(deps)

    # Build adjacency list for all nodes, ensuring every node has an entry
    adj = {node: list(graph.get(node, [])) for node in all_nodes}

    # Compute in-degrees
    indegree = {node: 0 for node in all_nodes}
    for node in adj:
        for neighbor in adj[node]:
            indegree[neighbor] += 1

    # Initialize queue with nodes that have zero in-degree, sorted alphabetically for determinism
    queue = deque(sorted([node for node in all_nodes if indegree[node] == 0]))

    result = []
    while queue:
        node = queue.popleft()
        result.append(node)
        # For each neighbor, reduce in-degree and if it becomes zero, add to queue in sorted order
        for neighbor in sorted(adj[node]):
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                # Insert into queue maintaining sorted order (simple insertion)
                # Since queue is small, we can just collect and sort later
                # But we want deterministic order: any new zero-indegree nodes should be added in sorted order
                queue.append(neighbor)
        # Re-sort the queue to maintain deterministic order
        queue = deque(sorted(queue))

    # Check for cycle
    if len(result) != len(all_nodes):
        raise ValueError("Graph contains a cycle")

    return result
